begin;set local role postgres;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions,pgtap;select plan(84);
select ok(to_regclass(format('public.%I',table_name))is not null,format('tabela %s existe',table_name))from unnest(array['erp_agent_installations','erp_agent_pairings','erp_agent_peripherals','erp_agent_commands','erp_agent_command_attempts','erp_agent_events','erp_offline_snapshots','erp_offline_sequence_reservations','erp_offline_operations','erp_offline_sync_conflicts','erp_agent_versions','erp_agent_update_policies'])names(table_name);
select ok(c.relrowsecurity,format('RLS ativo em %s',c.relname))from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['erp_agent_installations','erp_agent_pairings','erp_agent_peripherals','erp_agent_commands','erp_agent_command_attempts','erp_agent_events','erp_offline_snapshots','erp_offline_sequence_reservations','erp_offline_operations','erp_offline_sync_conflicts','erp_agent_versions','erp_agent_update_policies'])order by c.relname;
select ok(not has_table_privilege('anon',format('public.%I',table_name),'SELECT'),format('anon não lê %s',table_name))from unnest(array['erp_agent_installations','erp_agent_pairings','erp_agent_commands','erp_offline_snapshots','erp_offline_operations','erp_agent_versions'])names(table_name);
select ok(has_table_privilege('authenticated',format('public.%I',table_name),'SELECT'),format('authenticated lê %s sob RLS',table_name))from unnest(array['erp_agent_installations','erp_agent_peripherals','erp_agent_commands','erp_offline_operations','erp_offline_sync_conflicts','erp_agent_versions'])names(table_name);
select ok(not has_table_privilege('authenticated',format('public.%I',table_name),'INSERT'),format('authenticated não insere diretamente em %s',table_name))from unnest(array['erp_agent_installations','erp_agent_commands','erp_offline_operations','erp_agent_versions'])names(table_name);
select is((select count(*)::integer from public.erp_permissions where key in('agent.read','agent.manage','peripheral.manage','offline.sync','agent.audit')),5,'cinco permissões M12 existem');
select ok(not has_function_privilege('anon','public.erp_create_agent_pairing(uuid,uuid,text)','EXECUTE'),'anon não cria pareamento');select ok(has_function_privilege('authenticated','public.erp_create_agent_pairing(uuid,uuid,text)','EXECUTE'),'authenticated cria pareamento por RPC');
select ok(not has_function_privilege('anon','public.erp_revoke_agent(uuid,uuid,text,text)','EXECUTE'),'anon não revoga agente');select ok(has_function_privilege('authenticated','public.erp_revoke_agent(uuid,uuid,text,text)','EXECUTE'),'authenticated revoga agente por RPC');
select ok(not has_function_privilege('anon','public.erp_queue_agent_command(uuid,uuid,uuid,text,jsonb,text,text,text)','EXECUTE'),'anon não enfileira comando');select ok(has_function_privilege('authenticated','public.erp_queue_agent_command(uuid,uuid,uuid,text,jsonb,text,text,text)','EXECUTE'),'authenticated enfileira por RPC');
select ok(not has_function_privilege('anon','public.erp_resolve_offline_operation(uuid,uuid,text,text,text)','EXECUTE'),'anon não resolve offline');select ok(has_function_privilege('authenticated','public.erp_resolve_offline_operation(uuid,uuid,text,text,text)','EXECUTE'),'authenticated resolve offline por RPC');
select ok((select prosecdef from pg_proc where oid='public.erp_create_agent_pairing(uuid,uuid,text)'::regprocedure),'pareamento security definer');
select ok((select prosecdef from pg_proc where oid='public.erp_revoke_agent(uuid,uuid,text,text)'::regprocedure),'revogação security definer');
select ok((select prosecdef from pg_proc where oid='public.erp_queue_agent_command(uuid,uuid,uuid,text,jsonb,text,text,text)'::regprocedure),'comando security definer');
select ok((select prosecdef from pg_proc where oid='public.erp_resolve_offline_operation(uuid,uuid,text,text,text)'::regprocedure),'offline security definer');
select ok(exists(select 1 from pg_constraint where conname='erp_agent_installations_tenant_id_code_key'),'agente único por tenant');
select ok(exists(select 1 from pg_constraint where conname='erp_agent_pairings_tenant_id_code_hash_key'),'código de pareamento único');
select ok(exists(select 1 from pg_constraint where conname='erp_agent_peripherals_tenant_id_agent_id_logical_code_key'),'periférico lógico único');
select ok(exists(select 1 from pg_constraint where conname='erp_agent_commands_tenant_id_idempotency_key_key'),'comando idempotente');
select ok(exists(select 1 from pg_constraint where conname='erp_agent_commands_tenant_id_nonce_hash_key'),'nonce não repete');
select ok(exists(select 1 from pg_constraint where conname='erp_offline_snapshots_tenant_id_establishment_id_version_key'),'snapshot versionado');
select ok(exists(select 1 from pg_constraint where conname='erp_offline_operations_tenant_id_operation_id_key'),'operação offline idempotente');
select ok(exists(select 1 from pg_constraint where conname='erp_offline_operations_tenant_id_agent_id_sequence_key'),'sequência offline única');
select ok(pg_get_functiondef('public.erp_create_agent_pairing(uuid,uuid,text)'::regprocedure)like '%current_aal()%','pareamento exige AAL2');
select ok(pg_get_functiondef('public.erp_queue_agent_command(uuid,uuid,uuid,text,jsonb,text,text,text)'::regprocedure)like '%secret field forbidden%','comando rejeita segredos');
select ok(pg_get_functiondef('public.erp_revoke_agent(uuid,uuid,text,text)'::regprocedure)like '%agent_revoked%','revogação cancela comandos');
select ok(not has_function_privilege('authenticated','public.erp_activate_agent_pairing(uuid,text,text,text,text,text)','EXECUTE'),'authenticated não ativa agente');select ok(has_function_privilege('service_role','public.erp_activate_agent_pairing(uuid,text,text,text,text,text)','EXECUTE'),'somente broker ativa agente');
select ok(not has_function_privilege('authenticated','public.erp_record_agent_command_result(uuid,uuid,uuid,text,text,text,text,text,text)','EXECUTE'),'authenticated não registra resultado');select ok(has_function_privilege('service_role','public.erp_record_agent_command_result(uuid,uuid,uuid,text,text,text,text,text,text)','EXECUTE'),'broker registra resultado');
select ok(not has_function_privilege('authenticated','public.erp_ingest_signed_offline_operation(uuid,uuid,uuid,uuid,uuid,text,bigint,text,text,jsonb,timestamptz,text,text)','EXECUTE'),'authenticated não ingere offline');select ok(has_function_privilege('service_role','public.erp_ingest_signed_offline_operation(uuid,uuid,uuid,uuid,uuid,text,bigint,text,text,jsonb,timestamptz,text,text)','EXECUTE'),'broker ingere offline assinado');
select ok((select prosecdef from pg_proc where oid='public.erp_activate_agent_pairing(uuid,text,text,text,text,text)'::regprocedure),'ativação security definer');
select ok((select prosecdef from pg_proc where oid='public.erp_record_agent_command_result(uuid,uuid,uuid,text,text,text,text,text,text)'::regprocedure),'resultado security definer');
select ok((select prosecdef from pg_proc where oid='public.erp_ingest_signed_offline_operation(uuid,uuid,uuid,uuid,uuid,text,bigint,text,text,jsonb,timestamptz,text,text)'::regprocedure),'ingestão assinada security definer');
select ok(exists(select 1 from pg_constraint where conname='erp_agent_installations_tenant_id_establishment_id_id_key'),'agente vinculado ao estabelecimento');
select ok(exists(select 1 from pg_constraint where conname='erp_agent_commands_tenant_id_agent_id_peripheral_id_fkey'),'comando usa periférico do mesmo agente');
select ok(exists(select 1 from pg_constraint where conname='erp_offline_snapshots_context_id_key'),'snapshot preserva agente e estabelecimento');
select ok(exists(select 1 from pg_constraint where conname='erp_offline_operations_snapshot_context_fkey'),'operação usa snapshot do mesmo contexto');
select ok(exists(select 1 from pg_constraint where conname='erp_offline_operations_previous_hash_fkey'),'cadeia offline referencia hash anterior');
select ok(exists(select 1 from pg_policies where schemaname='public'and tablename='erp_agent_pairings'and qual like '%agent.manage%'),'pairings exigem gestão');
select ok(exists(select 1 from pg_policies where schemaname='public'and tablename='erp_agent_events'and qual like '%agent.audit%'),'eventos exigem auditoria');
select ok(exists(select 1 from pg_policies where schemaname='public'and tablename='erp_offline_operations'and qual like '%offline.sync%'),'offline exige sincronização ou auditoria');
select ok(pg_get_functiondef('public.erp_resolve_offline_operation(uuid,uuid,text,text,text)'::regprocedure)like '%current_aal()%','resolução offline exige AAL2');
select ok(pg_get_functiondef('public.erp_resolve_offline_operation(uuid,uuid,text,text,text)'::regprocedure)like '%idempotency_key%','resolução offline é idempotente');
select ok(exists(select 1 from pg_constraint where conrelid='public.erp_agent_commands'::regclass and pg_get_constraintdef(oid)like '%document_hash%'),'document hash validado');
select * from finish();rollback;
